import React from "react";
import {
  FaUser,
  FaPhone,
  FaMapMarkerAlt,
  FaImage,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaLink,
} from "react-icons/fa";

class CustomerRequestForm extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      fullName: "",
      mobile: "",
      landline: "",
      province: "",
      address: "",
      deviceType: "",
      deviceBrand: "",
      deviceIssue: "",
      visitTime: "",
      description: "",
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
  }

  handleChange(field) {
    return (e) => {
      this.setState({
        [field]: e.target.value,
      });
    };
  }

  handleSubmit(e) {
    e.preventDefault();

    console.log(this.state);
  }

  render() {
    const {
      fullName,
      mobile,
      landline,
      province,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
    } = this.state;

    return (
      <div dir="rtl" lang="fa" className="bg-light min-vh-100 py-4 px-3">

        <div className="mx-auto" style={{ maxWidth: "480px" }}>

          {/* عنوان */}
          <h6 className="text-center fw-bold text-dark mb-4">
            اطلاعات مشتری را با دقت ثبت کنید
          </h6>

          <form onSubmit={this.handleSubmit}>

            {/* نام کامل */}
            <div className="input-group mb-3">
              <span className="input-group-text bg-white border-end-0">
                <FaUser className="text-secondary" />
              </span>

              <input
                type="text"
                className="form-control border-start-0 shadow-none"
                placeholder="نام کامل"
                value={fullName}
                onChange={this.handleChange("fullName")}
                style={{ height: "52px" }}
              />
            </div>

            {/* شماره موبایل */}
            <div className="input-group mb-3">
              <span className="input-group-text bg-white border-end-0">
                <FaPhone className="text-secondary" />
              </span>

              <input
                type="tel"
                inputMode="numeric"
                className="form-control border-start-0 shadow-none"
                placeholder="شماره موبایل"
                value={mobile}
                onChange={this.handleChange("mobile")}
                style={{ height: "52px" }}
              />
            </div>

            {/* تلفن ثابت */}
            <div className="input-group mb-3">
              <span className="input-group-text bg-white border-end-0">
                <FaPhone className="text-secondary" />
              </span>

              <input
                type="tel"
                inputMode="numeric"
                className="form-control border-start-0 shadow-none"
                placeholder="تلفن ثابت"
                value={landline}
                onChange={this.handleChange("landline")}
                style={{ height: "52px" }}
              />
            </div>

            {/* استان */}
            <div className="input-group mb-3">
              <span className="input-group-text bg-white border-end-0">
                <FaMapMarkerAlt className="text-secondary" />
              </span>

              <select
                className="form-select border-start-0 shadow-none"
                value={province}
                onChange={this.handleChange("province")}
                style={{ height: "52px" }}
              >
                <option value="" disabled>
                  استان
                </option>

                <option value="tehran">تهران</option>
                <option value="isfahan">اصفهان</option>
                <option value="fars">فارس</option>
                <option value="khorasan-razavi">
                  خراسان رضوی
                </option>
                <option value="alborz">البرز</option>
              </select>
            </div>

            {/* آدرس */}
            <div className="input-group mb-3">
              <span className="input-group-text bg-white border-end-0">
                <FaMapMarkerAlt className="text-secondary" />
              </span>

              <input
                type="text"
                className="form-control border-start-0 shadow-none"
                placeholder="آدرس"
                value={address}
                onChange={this.handleChange("address")}
                style={{ height: "52px" }}
              />
            </div>

            {/* نوع دستگاه */}
            <div className="input-group mb-3">
              <span className="input-group-text bg-white border-end-0">
                <FaImage className="text-secondary" />
              </span>

              <select
                className="form-select border-start-0 shadow-none"
                value={deviceType}
                onChange={this.handleChange("deviceType")}
                style={{ height: "52px" }}
              >
                <option value="" disabled>
                  نوع دستگاه
                </option>

                <option value="washer">
                  ماشین لباسشویی
                </option>

                <option value="fridge">
                  یخچال
                </option>

                <option value="ac">
                  کولر گازی
                </option>

                <option value="tv">
                  تلویزیون
                </option>
              </select>
            </div>

            {/* برند دستگاه */}
            <div className="input-group mb-3">
              <span className="input-group-text bg-white border-end-0">
                <FaTag className="text-secondary" />
              </span>

              <select
                className="form-select border-start-0 shadow-none"
                value={deviceBrand}
                onChange={this.handleChange("deviceBrand")}
                style={{ height: "52px" }}
              >
                <option value="" disabled>
                  برند دستگاه
                </option>

                <option value="samsung">سامسونگ</option>
                <option value="lg">ال‌جی</option>
                <option value="snowa">اسنوا</option>
                <option value="pakshoma">پاکشوما</option>
              </select>
            </div>

            {/* ایراد دستگاه */}
            <div className="input-group mb-3">
              <span className="input-group-text bg-white border-end-0">
                <FaQuestionCircle className="text-secondary" />
              </span>

              <input
                type="text"
                className="form-control border-start-0 shadow-none"
                placeholder="ایراد دستگاه"
                value={deviceIssue}
                onChange={this.handleChange("deviceIssue")}
                style={{ height: "52px" }}
              />
            </div>

            {/* زمان مراجعه */}
            <div className="input-group mb-3">
              <span className="input-group-text bg-white border-end-0">
                <FaClock className="text-secondary" />
              </span>

              <input
                type="text"
                className="form-control border-start-0 shadow-none"
                placeholder="زمان مراجعه"
                value={visitTime}
                onChange={this.handleChange("visitTime")}
                style={{ height: "52px" }}
              />
            </div>

            {/* توضیحات */}
            <div className="input-group mb-3">
              <span className="input-group-text bg-white border-end-0">
                <FaLink className="text-secondary" />
              </span>

              <input
                type="text"
                className="form-control border-start-0 shadow-none"
                placeholder="توضیحات"
                value={description}
                onChange={this.handleChange("description")}
                style={{ height: "52px" }}
              />
            </div>

            {/* دکمه */}
            <button
              type="submit"
              className="btn btn-primary w-100 mt-2"
              style={{
                height: "52px",
                fontWeight: "bold",
                borderRadius: "8px",
              }}
            >
              ثبت درخواست
            </button>

          </form>
        </div>
      </div>
    );
  }
}

export default CustomerRequestForm;
